# Period::AccountType aggregates Period::Account objects by their STI type for a single year.
#
# Used to display summarized data by account type (e.g., "RRSP", "TFSA") rather than
# individual accounts. This reduces table width when a household has multiple accounts
# of the same type.
#
# Example: If a household has 3 RRSPs with balances of $100k, $50k, and $25k,
# this class would show a single "RRSP" row with $175k total.
#
# Generated by Period::Summary#account_types, which groups account_periods by type.
#
module Period
  class AccountType
    include Inspectable

    attr_reader :type, :type_name, :account_periods

    inspectable :type_name, :opening_balance, :net_flow, :growth, :ending_balance

    def initialize(type:, account_periods:)
      @type = type
      @type_name = type.demodulize.titleize
      @account_periods = account_periods
    end

    def opening_balance
      account_periods.sum(&:opening_balance)
    end

    def contribution_amount
      account_periods.sum(&:contribution_amount)
    end

    def withdrawal_amount
      account_periods.sum(&:withdrawal_amount)
    end

    def net_flow
      contribution_amount - withdrawal_amount
    end

    # Total change in value for the year (contributions - withdrawals + growth)
    def net_change
      ending_balance - opening_balance
    end

    def growth
      account_periods.sum(&:growth)
    end

    def ending_balance
      account_periods.sum(&:ending_balance)
    end
  end
end
